ALTER TABLE "portable_record_access_events" ADD CONSTRAINT "record_access_kind" CHECK ((("portable_record_access_events"."kind" IN ('contacts','companies','deals','tasks','leads','tickets') AND "portable_record_access_events"."custom_object_id" IS NULL) OR
    ("portable_record_access_events"."kind" IN ('products','quotes','invoices') AND "portable_record_access_events"."custom_object_id" IS NULL AND ("portable_record_access_events"."action" IN ('list','detail','csv') OR ("portable_record_access_events"."kind" IN ('quotes','invoices') AND "portable_record_access_events"."action"='document'))) OR
    ("portable_record_access_events"."kind"='custom-objects' AND "portable_record_access_events"."custom_object_id" IS NOT NULL AND "portable_record_access_events"."action" IN ('detail','list','search','related'))));--> statement-breakpoint
ALTER TABLE "portable_record_access_events" ADD CONSTRAINT "record_access_action" CHECK (("portable_record_access_events"."action" IN ('detail','list','csv','integration','search','report','related','history') OR ("portable_record_access_events"."action"='document' AND "portable_record_access_events"."kind" IN ('quotes','invoices'))) AND (("portable_record_access_events"."token_id" IS NOT NULL) = ("portable_record_access_events"."action"='integration')));--> statement-breakpoint
ALTER TABLE "portable_record_access_events" ADD CONSTRAINT "record_access_count" CHECK (cardinality("portable_record_access_events"."record_ids") BETWEEN 1 AND 500 AND ("portable_record_access_events"."action" NOT IN ('detail','document') OR cardinality("portable_record_access_events"."record_ids")=1));